items:
.input {$count :number}
.match $count
0 {{Your cart is empty}}
one {{{$count} item}}
* {{{$count} items}}

rank:
.input {$place :number select=ordinal}
.match $place
one {{You finished {$place}st}}
two {{You finished {$place}nd}}
few {{You finished {$place}rd}}
* {{You finished {$place}th}}

delivery:
.input {$method :string}
.match $method
pickup {{Collect it from {$store}}}
courier {{{$courier} delivers it on {$day :date style=long}}}
* {{Ships soon}}
